// ============ 模拟一组真实业务数据：电商订单 ============
const orders = [
  { id: 1, product: "机械键盘", price: 200, quantity: 2, status: "paid" },
  { id: 2, product: "无线鼠标", price: 80, quantity: 5, status: "pending" },
  { id: 3, product: "4K 显示器", price: 1500, quantity: 1, status: "paid" },
  { id: 4, product: "降噪耳机", price: 300, quantity: 3, status: "cancelled" },
  { id: 5, product: "USB 扩展坞", price: 150, quantity: 4, status: "paid" },
];

// ============ 1. filter：从数组中筛选出符合条件的元素 ============
// 回调返回 true 的元素会被保留，false 的会被丢弃
const paidOrders = orders.filter((order) => order.status === "paid");
console.log("已支付的订单:", paidOrders);
// 输出：3 条 status === "paid" 的订单对象

// ============ 2. map：把每个元素转换成另一种形态 ============
// 输入 3 个元素，输出仍然是 3 个元素，但形态变了
const summaries = paidOrders.map(
  (order) => `${order.product} × ${order.quantity} = ${
    order.price * order.quantity
  } 元`
);
console.log("订单摘要:", summaries);
// 输出: ['机械键盘 × 2 = 400 元', '4K 显示器 × 1 = 1500 元', 'USB 扩展坞 × 4 = 600 元']

// ============ 3. reduce：把整个数组汇总成一个值 ============
// sum 是累加器，0 是初始值（强烈建议总是提供初始值！）
const totalAmount = paidOrders.reduce(
  (sum, order) => sum + order.price * order.quantity,
  0
);
console.log("已支付订单总金额:", totalAmount); // 输出: 2500

// ============ 4. 链式调用：一行完成「筛选 + 计算」 ============
const finalTotal = orders
  .filter((order) => order.status === "paid")
  .reduce((sum, order) => sum + order.price * order.quantity, 0);
console.log("链式调用结果:", finalTotal); // 输出: 2500

// ============ 5. 常见陷阱演示：map 回调忘记 return ============
const badResult = orders.map((order) => {
  order.price * order.quantity; // ❌ 少了 return，结果全是 undefined
});
console.log("忘记 return 的后果:", badResult);

// 箭头函数简写（去掉花括号自动 return）是推荐写法 ✅
const goodResult = orders.map((order) => order.price * order.quantity);
console.log("正确写法的结果:", goodResult); // 输出: [400, 400, 1500, 900, 600]

// ============ 6. reduce 的进阶用法：按状态分组 ============
const grouped = orders.reduce((acc, order) => {
  // 如果该状态还没有桶，就创建一个空数组
  if (!acc[order.status]) acc[order.status] = [];
  acc[order.status].push(order);
  return acc; // 每次都要把累加器还回去
}, {});
console.log("按状态分组:", Object.keys(grouped)); // ['paid', 'pending', 'cancelled']

